  {"id":"f120","type":"flight","airline":"Cantabo","from":"Hamburg","fromCode":"HAM","to":"Osaka","toCode":"KIX","ziel":"kyoto","depart":"10:00","arrive":"01:55","duration":"15h 55m","stops":0,"price":750,"baggage":"Handgepäck inkl.","aircraft":"A330-300"}
