/* Mehr als eine Verbindung je Flughafen.
   ==================================================================
   Gemessen am 02.10.2026: 120 Fluege, 18 Ziele, 9 Flughaefen - aber
   109 von 123 Paaren aus Ziel und Flughafen hatten genau EINE
   Verbindung. Das Flugfenster (agent/fluege.js) braucht mindestens
   zwei, sonst gibt es nichts zu waehlen. Es waere also fast nie
   aufgegangen, und die Partner-Airline - das zweite Objekt der
   Erhebung - haette so gut wie nie stattgefunden.

   Deshalb bekommt jedes Paar drei Verbindungen, und sie unterscheiden
   sich in dem, worin sich Fluege wirklich unterscheiden: direkt gegen
   einen Stopp, Gepaeck inklusive gegen Handgepaeck, frueh gegen spaet,
   und der Preis dazu. Damit ist die Wahl eine echte Abwaegung und
   nicht eine Liste mit einem Gewinner - genau das, was die Erhebung
   braucht, um eine Kennzeichnung ueberhaupt wirken zu lassen.

   Alles abgeleitet: Die Zusatzfluege haengen am guenstigsten
   vorhandenen Flug des Paares, und ihre Kennung tragt dessen Nummer.
   Dieselbe Seite zeigt nach dem Neuladen dieselben Fluege.
   ================================================================== */
(() => {
  // Preisfaktor und Gepaeck je Airline - teurer heisst mehr inklusive
  /* Erfundene Fluggesellschaften.
     ----------------------------------------------------------------
     Bis zum 02.10.2026 standen hier echte Marken. Der Nutzer: "Ich
     glaube, es waere besser, wenn es quasi ausgedachte Marken sind,
     weil sonst habe ich das Gefuehl, ist halt schon so ein Vorwissen
     ueber die Marken da und dann wuerde man vielleicht einfach nehmen,
     ja, ich nehme die, die ich immer nehme."

     Genau das ist das Problem: Gemessen werden soll, ob die
     Kennzeichnung des Partnerflugs die Wahl veraendert. Wer eine Marke
     kennt und mag, waehlt nach Gewohnheit, und die Kennzeichnung ist
     nicht mehr der Unterschied zwischen den Angeboten, sondern einer
     von zweien. Die Namen hier haben deshalb absichtlich keinen
     Anklang an bestehende Gesellschaften. */
  const AIRLINES = [
    { name: "Arvela Air", gepaeck: "23 kg inkl.", faktor: 1.19 },
    { name: "Marenta", gepaeck: "23 kg inkl.", faktor: 1.07 },
    { name: "Solbrixa", gepaeck: "20 kg inkl.", faktor: 1.01 },
    { name: "Nordlin", gepaeck: "Handgepäck inkl.", faktor: 0.95 },
    { name: "Vireo", gepaeck: "Handgepäck inkl.", faktor: 0.90 },
    { name: "Cantabo", gepaeck: "nur kleines Handgepäck", faktor: 0.84 },
  ];

  const minuten = (dauer) => {
    const m = String(dauer).match(/(\d+)h\s*(\d+)?m?/);
    if (!m) return 150;
    return parseInt(m[1], 10) * 60 + (parseInt(m[2], 10) || 0);
  };
  const dauerText = (min) => `${Math.floor(min / 60)}h ${String(min % 60).padStart(2, "0")}m`;
  const uhrText = (min) => {
    const t = ((min % 1440) + 1440) % 1440;
    return `${String(Math.floor(t / 60)).padStart(2, "0")}:${String(t % 60).padStart(2, "0")}`;
  };
  const alsMinuten = (uhr) => {
    const [h, m] = String(uhr).split(":").map((x) => parseInt(x, 10));
    return (h || 0) * 60 + (m || 0);
  };

  /* Jeder Flughafen fliegt jedes Ziel an (03.10.2026).
     ----------------------------------------------------------------
     Gemeldet: "Flug ab Zuerich" - und der Agent legte Haeuser auf Kreta
     und Mallorca vor, wohin ab Zuerich nichts flog; auf der Hausseite
     stand dann "Ab Zuerich gibt es keinen Flug zu diesem Ziel". Von 162
     Paaren aus Flughafen und Ziel fehlten 48. Der Nutzer: Ein Flug muss
     immer gewaehrleistet sein, sonst laesst sich das Partneretikett beim
     Flug gar nicht messen.

     Fuer jedes fehlende Paar entsteht ein Basisflug aus den vorhandenen
     Fluegen zum selben Ziel: mittlere Dauer und Stopps, mittlerer Preis
     mit wenigen Prozent Abweichung je Flughafen. Daraus macht der
     Schritt darunter wie bei allen anderen Paaren drei eng beieinander
     liegende Verbindungen. */
  {
    const flughaefen = new Map();
    for (const f of FLIGHTS) if (!flughaefen.has(f.fromCode)) flughaefen.set(f.fromCode, f.from);
    const nachZiel = new Map();
    for (const f of FLIGHTS) {
      if (!nachZiel.has(f.ziel)) nachZiel.set(f.ziel, []);
      nachZiel.get(f.ziel).push(f);
    }
    const streu = (text) => { let h = 0; for (const c of text) h = (h * 31 + c.charCodeAt(0)) >>> 0; return h; };
    let nr = 500;
    for (const [ziel, liste] of nachZiel) {
      const nachPreis = liste.slice().sort((a, b) => a.price - b.price);
      const mitte = nachPreis[Math.floor(nachPreis.length / 2)];
      const nachDauer = liste.map((f) => minuten(f.duration)).sort((a, b) => a - b);
      const dauer = nachDauer[Math.floor(nachDauer.length / 2)];
      for (const [code, name] of flughaefen) {
        if (liste.some((f) => f.fromCode === code)) continue;
        const h = streu(`${ziel}|${code}`);
        const ab = 6 * 60 + (h % 12) * 60 + (h % 4) * 15;
        nr += 1;
        FLIGHTS.push({
          id: `f${nr}`, type: "flight", airline: mitte.airline,
          from: name, fromCode: code, to: mitte.to, toCode: mitte.toCode, ziel,
          depart: uhrText(ab), arrive: uhrText(ab + dauer), duration: dauerText(dauer),
          stops: mitte.stops || 0, price: Math.max(39, Math.round(mitte.price * (0.96 + (h % 9) / 100))),
          baggage: mitte.baggage, aircraft: mitte.aircraft, ergaenzt: true,
        });
      }
    }
  }

  // Paare aus Ziel und Flughafen, jeweils der guenstigste vorhandene Flug
  const paare = new Map();
  for (const f of FLIGHTS) {
    const k = `${f.ziel}|${f.fromCode}`;
    const da = paare.get(k);
    if (!da || f.price < da.price) paare.set(k, f);
  }

  const dazu = [];
  for (const [k, basis] of paare) {
    const vorhanden = FLIGHTS.filter((f) => `${f.ziel}|${f.fromCode}` === k);
    if (vorhanden.length >= 3) continue;
    const nummer = parseInt(String(basis.id).replace(/\D/g, ""), 10) || 1;
    const genutzt = new Set(vorhanden.map((f) => f.airline));
    const basisMin = minuten(basis.duration);
    const abflug = alsMinuten(basis.depart);

    /* Drei Verbindungen, die sich kaum unterscheiden - mit Absicht.
       ----------------------------------------------------------------
       Erst standen hier zwei Rollen: eine guenstige mit Stopp und wenig
       Gepaeck, eine bequeme mit Gepaeck. Das war als echte Abwaegung
       gedacht, ist aber fuer diese Erhebung falsch. Der Nutzer am
       02.10.2026: "Mach einfach, dass die Fluege super aehnlichen
       Kostenpunkt haben. Also dass es eigentlich keinen Grund gibt, den
       Partnerflug rauszunehmen, weil er eigentlich gleiche Sachen bietet
       wie die anderen auch."

       Genau wie beim Vergleichsset der Haeuser: Unterscheiden sich die
       Angebote in Preis, Stopps oder Gepaeck, entscheidet das - und nicht
       die Kennzeichnung, die gemessen werden soll. Die Verbindungen
       unterscheiden sich deshalb nur noch in Airline und Abflugzeit; die
       Stopps sind dieselben wie beim Basisflug, das Gepaeck gleichwertig,
       und der Preis liegt innerhalb weniger Prozent. */
    const rollen = [
      { art: "frueher", stops: basis.stops || 0, extra: 8, versatz: -150, faktor: 0.97 },
      { art: "spaeter", stops: basis.stops || 0, extra: -6, versatz: 205, faktor: 1.035 },
    ];

    for (let i = 0; i < rollen.length && vorhanden.length + dazu.filter((d) => `${d.ziel}|${d.fromCode}` === k).length < 3; i++) {
      const r = rollen[i];
      /* Eine Airline, die hier noch nicht fliegt. Welche, haengt an der
         Nummer des Basisflugs - fest, aber je Paar verschieden. Das
         Gepaeck wird gleichgezogen: Wer weniger mitnehmen darf, hat einen
         Grund zur Wahl, der nichts mit der Kennzeichnung zu tun hat. */
      const pool = AIRLINES.filter((x) => !genutzt.has(x.name));
      if (!pool.length) continue;
      const a = pool[(nummer + i * 3) % pool.length];
      genutzt.add(a.name);

      const dauerMin = Math.max(45, basisMin + r.extra);
      const ab = abflug + r.versatz + (nummer % 5) * 15;
      // Wenige Prozent um den Basispreis herum, mehr nicht
      const preis = Math.max(39, Math.round(basis.price * r.faktor));
      dazu.push({
        id: `f${nummer}v${i + 2}`, type: "flight", airline: a.name,
        from: basis.from, fromCode: basis.fromCode, to: basis.to, toCode: basis.toCode,
        ziel: basis.ziel, depart: uhrText(ab), arrive: uhrText(ab + dauerMin),
        duration: dauerText(dauerMin), stops: r.stops, price: preis,
        baggage: basis.baggage, aircraft: basis.aircraft,
      });
    }
  }
  FLIGHTS.push(...dazu);

  /* Zeiten eng, Preise konstruiert (03.10.2026).
     ----------------------------------------------------------------
     Gemeldet: Die drei Verbindungen eines Fensters starteten um 07:16,
     09:31 und 13:11 - die Uhrzeit wird dann zum Grund der Wahl, nicht die
     Kennzeichnung. Und der Nutzer will, dass das Partnerangebot leicht
     bessere Konditionen hat, damit sich sagen laesst: obwohl es guenstiger
     war, wurde es (nicht) gewaehlt.

     Je Paar aus Ziel und Flughafen, nach Abflug sortiert:
     - Abflug: die mittlere Zeit, die erste 35 Minuten frueher, die dritte
       40 Minuten spaeter; dieselbe Flugdauer fuer alle.
     - Preis: die erste (das Fenster zeigt sie oben; Partner ist die erste
       Zeile) 2,5 Prozent unter der mittleren, die dritte 1,2 Prozent
       darueber. Weitere Verbindungen liegen knapp ueber der dritten. */
  const gruppen = new Map();
  for (const f of FLIGHTS) {
    const k = `${f.ziel}|${f.fromCode}`;
    if (!gruppen.has(k)) gruppen.set(k, []);
    gruppen.get(k).push(f);
  }
  for (const liste of gruppen.values()) {
    if (liste.length < 2) continue;
    liste.sort((a, b) => alsMinuten(a.depart) - alsMinuten(b.depart));
    const mitte = liste[Math.min(1, liste.length - 1)];
    const ab = alsMinuten(mitte.depart);
    const dauer = minuten(mitte.duration);
    const preis = mitte.price;
    const versatz = [-35, 0, 40, 75, 110];
    const faktor = [0.975, 1, 1.012, 1.02, 1.028];
    liste.forEach((f, i) => {
      const start = ab + (versatz[i] ?? 110 + i * 10);
      f.depart = uhrText(start);
      f.arrive = uhrText(start + dauer);
      f.duration = dauerText(dauer);
      f.stops = mitte.stops || 0;
      f.baggage = mitte.baggage;
      f.price = Math.max(39, Math.round(preis * (faktor[i] ?? 1.03)));
    });
  }

  /* Drei Tageszeiten je Flughafen und Ziel (04.10.2026).
     ----------------------------------------------------------------
     Wunsch des Nutzers: Der Agent zeigt drei Verbindungen und fragt, ob
     die Uhrzeit passt oder ob er andere heraussuchen soll - "und dann
     halt wieder nach dem gleichen Schema". Dafuer braucht es je Paar
     mehr als eine Gruppe. Die vorhandene Gruppe bleibt, wo sie ist; zu
     den beiden anderen Tageszeiten (frueh um 07:00, mittags um 12:30,
     abends um 18:00) kommt je eine Gruppe nach demselben Bauplan dazu:
     drei Verbindungen, 35 Minuten frueher bis 40 Minuten spaeter, gleiche
     Dauer, Stopps und Gepaeck, die erste 2,5 Prozent guenstiger. Die
     Gruppen untereinander liegen im Preis wenige Prozent auseinander. */
  const ZEITEN = [{ id: "frueh", mitte: 7 * 60 }, { id: "mittag", mitte: 12 * 60 + 30 }, { id: "abend", mitte: 18 * 60 }];
  const fenster = (min) => ZEITEN.reduce((a, b) => (Math.abs(b.mitte - min) < Math.abs(a.mitte - min) ? b : a)).id;
  const neueGruppen = [];
  let nrZeit = 900;
  for (const liste of gruppen.values()) {
    liste.sort((a, b) => alsMinuten(a.depart) - alsMinuten(b.depart));
    const mitte = liste[Math.min(1, liste.length - 1)];
    const eigenes = fenster(alsMinuten(mitte.depart));
    for (const f of liste) f.zeitfenster = eigenes;
    const dauer = minuten(mitte.duration);
    const genutzt = new Set(liste.map((f) => f.airline));
    const pool = AIRLINES.filter((x) => !genutzt.has(x.name));
    ZEITEN.filter((z) => z.id !== eigenes).forEach((z, zi) => {
      const zeitFaktor = z.id === "frueh" ? 0.97 : z.id === "abend" ? 0.99 : 1.0;
      // Ein Versatz fuer die ganze Gruppe, nicht je Flug - sonst laeuft
      // die Gruppe ueber die 80 Minuten hinaus, die die Pruefung erlaubt
      const gruppenVersatz = ((nrZeit * 7) % 4) * 5;
      [-35, 0, 40].forEach((v, i) => {
        nrZeit += 1;
        const a = pool[(zi * 3 + i) % (pool.length || 1)] || { name: mitte.airline };
        const start = z.mitte + v + gruppenVersatz;
        neueGruppen.push({
          id: `f${nrZeit}`, type: "flight", airline: a.name,
          from: mitte.from, fromCode: mitte.fromCode, to: mitte.to, toCode: mitte.toCode, ziel: mitte.ziel,
          depart: uhrText(start), arrive: uhrText(start + dauer), duration: dauerText(dauer),
          stops: mitte.stops || 0, price: Math.max(39, Math.round(mitte.price * zeitFaktor * [0.975, 1, 1.012][i])),
          baggage: mitte.baggage, aircraft: mitte.aircraft, zeitfenster: z.id,
        });
      });
    });
  }
  FLIGHTS.push(...neueGruppen);
})();


/* Mietwagen: je Ziel und Klasse drei aehnliche Wagen (03.10.2026).
   ------------------------------------------------------------------
   Wunsch des Nutzers: Der Agent sucht auf Wunsch einen Mietwagen,
   schlaegt drei vor, einer davon ist der Partnerwagen - "im besten Fall
   drei Autos, die aehnlich sind, sodass dadurch kein Bias entsteht".
   Dieselbe Regel wie bei Fluegen und Haeusern: Unterscheiden sich die
   Wagen in Sitzen, Getriebe, Gepaeck oder Storno, entscheidet das und
   nicht die Kennzeichnung.

   Je Ziel und Klasse (Kleinwagen, Kompaktklasse, SUV, Van) gibt es
   danach mindestens drei Wagen verschiedener Vermieter mit gleichen
   Merkmalen; die Preise liegen wenige Prozent auseinander, der
   guenstigste ist der Partnerwagen (partnerwagen: true). Fehlende Wagen
   entstehen aus einem vorhandenen derselben Klasse; ihr Bild ist das
   der Klasse ("oder aehnlich", siehe titelbildVon). */
(function mietwagenGruppen() {
  const KLASSEN = ["Kleinwagen", "Kompaktklasse", "SUV", "Van (7 Sitze)"];
  const MODELLE = {
    "Kleinwagen": ["Fiat Panda", "Toyota Aygo X", "Kia Picanto", "Hyundai i10", "Citroën C3", "Seat Ibiza"],
    "Kompaktklasse": ["VW Golf", "Opel Astra", "Ford Focus", "Peugeot 308", "Škoda Scala", "Toyota Corolla"],
    "SUV": ["Nissan Qashqai", "Peugeot 3008", "Kia Sportage", "Hyundai Tucson", "Škoda Karoq", "VW T-Roc"],
    "Van (7 Sitze)": ["VW Touran", "Citroën Grand C4", "Opel Zafira Life", "Ford Galaxy", "Dacia Jogger", "Toyota Proace Verso"],
  };
  const VERMIETER = ["Solmar Mietwagen", "Brisa Cars", "Kardia Rent", "Velora Drive", "Portino Autovermietung", "Atlanto Cars", "Nordwerk Mobil", "Pinia Rent"];
  const FAKTOR = [0.97, 1, 1.015, 1.025, 1.035, 1.045, 1.055, 1.065, 1.075, 1.085, 1.095, 1.1, 1.11, 1.12];
  const ziele = [...new Set(CARS.map((c) => c.ziel))];
  const schnitt = (xs) => xs.reduce((a, b) => a + b, 0) / (xs.length || 1);
  const alleSchnitt = schnitt(CARS.map((c) => c.pricePerDay));
  let nr = 200;
  for (const ziel of ziele) {
    const hier = CARS.filter((c) => c.ziel === ziel);
    const zielFaktor = schnitt(hier.map((c) => c.pricePerDay)) / alleSchnitt;
    const pickup = hier[0].pickup;
    for (const klasse of KLASSEN) {
      let gruppe = CARS.filter((c) => c.ziel === ziel && c.category === klasse);
      let basis = gruppe.slice().sort((a, b) => a.pricePerDay - b.pricePerDay)[Math.floor(gruppe.length / 2)];
      if (!basis) {
        const vorlage = CARS.find((c) => c.category === klasse);
        if (!vorlage) continue;
        basis = { ...vorlage, pricePerDay: Math.round(vorlage.pricePerDay * zielFaktor), ziel, pickup };
      }
      const modelle = MODELLE[klasse].filter((m) => !gruppe.some((g) => g.model === m));
      const vermieter = VERMIETER.filter((v) => !gruppe.some((g) => g.supplier === v));
      while (gruppe.length < 3) {
        nr += 1;
        const neu = { ...basis, id: `c${nr}`, ziel, pickup,
          model: modelle.shift() || basis.model, supplier: vermieter.shift() || basis.supplier,
          reviewCount: 150 + ((nr * 37) % 400) };
        CARS.push(neu);
        gruppe.push(neu);
      }
      // Gleiche Merkmale, Preise eng, der guenstigste vorn
      gruppe.sort((a, b) => a.pricePerDay - b.pricePerDay);
      gruppe.forEach((c, i) => {
        c.seats = basis.seats; c.doors = basis.doors; c.bags = basis.bags;
        c.transmission = basis.transmission; c.fuel = basis.fuel; c.aircon = true;
        c.freeCancellation = true; c.mileage = "Unbegrenzte Kilometer";
        // Dieselbe Note fuer alle: Eine schlechtere Note beim Partner waere
        // ein Grund gegen ihn, der nichts mit der Kennzeichnung zu tun hat
        c.rating = Math.round((basis.rating || 4.3) * 10) / 10;
        c.pricePerDay = Math.max(15, Math.round(basis.pricePerDay * (FAKTOR[i] ?? 1.12)));
        c.partnerwagen = i === 0;
      });
      // Der Partnerwagen echt guenstiger, auch nach dem Runden
      if (gruppe[1] && gruppe[0].pricePerDay >= gruppe[1].pricePerDay) gruppe[0].pricePerDay = gruppe[1].pricePerDay - 1;
    }
  }
})();

/* ==================================================================
   Pool und Sauna bei den Ferienwohnungen (03.11.2026)
   ------------------------------------------------------------------
   Gemessen am 03.11.2026: Von 66 sinnvollen Kombinationen aus Region und
   Filter lieferten bei den Ferienwohnungen 47 keine vier preislich
   vergleichbaren Objekte. Der groesste einzelne Grund war die
   Ausstattung: 28 von 202 Wohnungen hatten einen Pool, 15 eine Sauna.
   "Familie, Sommer, Pool" ergab in acht Regionen NULL Treffer - eine
   Sackgasse, und zwar bei einer Vorgabe, die niemand ausgefallen nennen
   wuerde.

   Warum nicht einfach neue Wohnungen? Weil die fehlende Ausstattung hier
   nicht nur eine Luecke in der Messung ist, sondern auch unrealistisch:
   Ferienwohnungen am Mittelmeer liegen ueberwiegend in Anlagen mit
   Gemeinschaftspool, und ein finnisches Ferienhaus OHNE Sauna gibt es
   praktisch nicht. Der Katalog bildete das bisher nicht ab.

   Dass die Daten dabei stimmig bleiben, kommt von selbst: Die
   Bewertungen werden aus den Aspekten erzeugt (`bewertungenFuer`),
   und die Aspekte haengen an der Ausstattung. Wer hier einen Pool
   eintraegt, bekommt Stimmen, die vom Pool sprechen - nachgemessen: aus
   0 von 20 werden 4 von 20. Nur der Beschreibungstext kommt nicht von
   selbst, deshalb steht hier auch ein Satz dafuer.

   Nicht angefasst: Wohnungen, bei denen beides unglaubwuerdig waere -
   Stadtwohnungen in Wien, Lissabon, New York, Kyoto und Barcelona. Wer
   dort einen Pool sucht, bekommt weiter die Rueckfrage des Agenten, dass
   die Vorgabe sehr einschraenkt. Das ist die richtige Antwort, keine
   Luecke.
   ================================================================== */
(function wohnungenAusstattung() {
  // Wo ein Gemeinschaftspool zur Anlage gehoert, und wo eine Sauna
  const MIT_POOL = ["mallorca", "kreta", "algarve", "sardinien", "teneriffa", "krabi", "kapstadt", "marrakesch"];
  /* Dachpool oder Pool im Innenhof: In einer Stadtresidenz ist das keine
     Seltenheit, und ohne diese Wohnungen ergab "Familie mit Pool" in
     Barcelona, Lissabon, Wien und New York null Treffer. Vier Staedte,
     keine weiteren - in Kyoto und Marrakesch waere es eine Behauptung. */
  const STADT_POOL = ["barcelona", "lissabon", "wien", "newyork"];
  /* Hallenbad statt Freibad: In den Alpen und an der Ostsee gehoert zu
     einer Ferienwohnanlage haeufig ein Schwimmbad im Haus - gerade im
     Winter. Ohne sie ergab "Familie, Sommer, Pool" in Tirol, Suedtirol
     und an der Ostsee NULL Treffer. */
  const MIT_HALLENBAD = ["tirol", "suedtirol", "ostsee"];
  const MIT_SAUNA = ["tirol", "suedtirol", "lappland", "ostsee", "island"];
  /* Wellness in den Stadtresidenzen: "spa" steht in der Filterspalte der
     Ferienwohnungen (results.js, APT_AMENITIES), den Haken gab es aber
     nur im Norden - "Paar, Winter, Wellness" ergab in Wien NULL Treffer.
     Ein kleiner Wellnessbereich im Haus ist in einer Stadtresidenz
     ueblich. An den warmen Kuesten bleibt es absichtlich leer: Eine
     Sauna in eine Strandwohnung in Krabi zu schreiben, nur damit eine
     Messung aufgeht, waere eine Behauptung - dort ist "nichts gefunden"
     die richtige Antwort, und der Agent bietet dann Hotels an. Dieselbe
     Begruendung steht in agent/auswahl-messen.cjs. */
  const MIT_WELLNESS = ["barcelona", "wien", "lissabon", "newyork", "kyoto"];
  /* Marrakesch ist die Ausnahme unter den warmen Zielen: Ein Hammam
     gehoert zu einem Riad, das ist keine erfundene Ausstattung. */
  const MIT_HAMMAM = ["marrakesch"];
  /* Die Zielzahlen stammen aus der Messung: Je Region gibt es seit dem
     Ausbau zwanzig Wohnungen, und damit nach Saison und zwei Filtern
     noch acht uebrigbleiben, muss gut die Haelfte das Merkmal haben.
     Mit neun reichte es nicht (elf Kombinationen lagen darunter), mit
     zwoelf schon. */
  /* 14 statt 12 am 04.11.2026: Mit zwoelf lagen 19 Kombinationen unter acht
     Objekten, sobald ueber ALLE Saisonmonate gemessen wird statt ueber einen
     je Kette - die Belegungssimulation nimmt je Monat andere Haeuser heraus,
     und bei zwoelf von zwanzig reichte die Luft nicht. */
  const ZIEL_POOL = 14;   // je Region, mindestens
  const ZIEL_SAUNA = 14;
  const ZIEL_STADTPOOL = 13;
  const ZIEL_STRAND = 14; // Wohnungen hoechstens 500 m vom Strand

  const satzPool = "Zur Anlage gehört ein Gemeinschaftspool mit Liegen, der allen Wohnungen offensteht.";
  const satzHalle = "Im Haus gibt es ein kleines Hallenbad, das allen Wohnungen offensteht.";
  const satzStadt = "Auf dem Dach des Hauses liegt ein kleiner Pool, der den Wohnungen offensteht.";
  const satzSauna = "Im Haus gibt es eine Sauna, die sich die Wohnungen teilen; Handtücher liegen bereit.";
  const satzWellness = "Zur Anlage gehört ein kleiner Wellnessbereich mit Sauna und Ruheraum, der allen Wohnungen offensteht.";
  const satzHammam = "Im Haus gibt es ein kleines Hammam mit Ruheraum, das den Wohnungen offensteht.";

  /* Welche Wohnung zuerst? Die groessten - eine Familie, die nach Pool
     sucht, reist zu viert, und genau diese Kombination fehlte. Bei
     gleicher Groesse entscheidet die Kennung, damit die Auswahl bei
     jedem Laden dieselbe ist. */
  const reihenfolge = (liste) => liste.slice().sort((a, b) =>
    (b.maxGuests || 0) - (a.maxGuests || 0) || a.id.localeCompare(b.id));

  /* Ein Wellnessbereich gehoert zum Haus, nicht zur Wohnungsgroesse -
     die Wohnungen eines Hauses liegen im selben Preisband. Deshalb wird
     er nicht an die groessten Wohnungen vergeben, sondern an einen
     zusammenhaengenden Block in der Mitte der Preisspanne. In New York
     lagen sonst acht Wellnesswohnungen so verstreut, dass kein
     preislich vergleichbarer Vierer mehr zusammenkam (04.11.2026). */
  const nachPreisband = (liste, wieViele) => {
    const sortiert = liste.slice().sort((a, b) =>
      (a.pricePerNight || 0) - (b.pricePerNight || 0) || a.id.localeCompare(b.id));
    const start = Math.max(0, Math.floor((sortiert.length - wieViele) / 2));
    return sortiert.slice(start, start + wieViele);
  };

  const ergaenzen = (ziele, merkmal, ziel, satz, bandweise = false) => {
    for (const z of ziele) {
      const alle = APARTMENTS.filter((w) => w.ziel === z);
      const schon = alle.filter((w) => (w.amenities || []).includes(merkmal));
      const fehlt = Math.max(0, ziel - schon.length);
      const frei = alle.filter((w) => !(w.amenities || []).includes(merkmal));
      const offen = bandweise ? nachPreisband(frei, fehlt) : reihenfolge(frei);
      for (const w of offen.slice(0, fehlt)) {
        w.amenities = [...(w.amenities || []), merkmal];
        // Der Text soll sagen, was die Filterspalte behauptet
        if (w.description && !w.description.includes(satz)) w.description += ` ${satz}`;
      }
    }
  };

  ergaenzen(MIT_POOL, "pool", ZIEL_POOL, satzPool);
  ergaenzen(MIT_HALLENBAD, "pool", ZIEL_POOL, satzHalle);
  ergaenzen(STADT_POOL, "pool", ZIEL_STADTPOOL, satzStadt);
  ergaenzen(MIT_SAUNA, "spa", ZIEL_SAUNA, satzSauna);
  ergaenzen(MIT_WELLNESS, "spa", ZIEL_SAUNA, satzWellness, true);
  ergaenzen(MIT_HAMMAM, "spa", ZIEL_SAUNA, satzHammam, true);

  /* Strandnaehe: In den Strandregionen lagen bis zu neun von elf
     Wohnungen weiter als 500 m vom Wasser - das traf "Strandnaehe" als
     Filter hart und war nebenbei unrealistisch, weil sich
     Ferienwohnungen an der Kueste genau dort draengen. Angehoben wird
     bei den Wohnungen, die ohnehin am naechsten liegen, und nur bis 300
     m - nicht "direkt am Strand", das bleibt den Haeusern vorbehalten,
     die es wirklich sind. */
  for (const z of [...new Set(APARTMENTS.map((w) => w.ziel))]) {
    const ziel = typeof ZIEL_NACH_ID !== "undefined" ? ZIEL_NACH_ID[z] : null;
    const amMeer = ziel && (ziel.typ === "strand" || ["kapstadt", "barcelona", "krabi"].includes(z));
    if (!amMeer) continue;
    const alle = APARTMENTS.filter((w) => w.ziel === z);
    const nah = alle.filter((w) => (w.distanceToBeach ?? 99) <= 0.5).length;
    const rest = alle.filter((w) => (w.distanceToBeach ?? 99) > 0.5)
      .sort((a, b) => (a.distanceToBeach ?? 99) - (b.distanceToBeach ?? 99));
    for (const w of rest.slice(0, Math.max(0, ZIEL_STRAND - nah))) w.distanceToBeach = 0.3;
  }
})();

// Ausstattungs-Labels, die es nur bei Ferienwohnungen gibt
Object.assign(AMENITY_LABELS, {
  kitchen: "Eigene Küche",
  washer: "Waschmaschine",
  balcony: "Balkon oder Terrasse",
});

const APARTMENT_BREAKDOWN_LABELS = {
  lage: "Lage",
  sauberkeit: "Sauberkeit",
  ausstattung: "Ausstattung",
  preis: "Preis-Leistung",
  kommunikation: "Kommunikation",
  checkin: "Check-in",
};

// Einheitlicher Zugriff ueber alle Bestaende
function getItemById(id) {
  return (
    HOTELS.find((h) => h.id === id) ||
    APARTMENTS.find((a) => a.id === id) ||
    CARS.find((c) => c.id === id) ||
    FLIGHTS.find((f) => f.id === id) ||
    null
  );
}

function itemPrice(item) {
  if (item.pricePerNight) return item.pricePerNight;
  if (item.pricePerDay) return item.pricePerDay;
  return item.price || 0;
}

function itemTitle(item) {
  return item.name || item.model || `${item.airline} ${item.fromCode}–${item.toCode}`;
}
